 long student(JdbcTemplate j,String email){return j.queryForObject("INSERT INTO student_users(email,password_hash,full_name,education_stage,email_verified,account_status,terms_accepted_at) VALUES (?,'synthetic','Private learner','HIGH_SCHOOL',TRUE,'ACTIVE',CURRENT_TIMESTAMP) RETURNING id",Long.class,email);}
 long lesson(JdbcTemplate j,long module,int duration){return j.queryForObject("INSERT INTO learning_lessons(module_id,title,status,validation_status,media_key,duration_seconds) VALUES (?,'Synthetic short video','PUBLISHED','READY',?,?) RETURNING id",Long.class,module,UUID.randomUUID(),duration);}
 void complete(JdbcTemplate j,long sid,long lesson){j.update("INSERT INTO learning_lesson_progress(student_id,lesson_id,position_seconds,watched_seconds,completed_at) VALUES (?,?,300,300,CURRENT_TIMESTAMP)",sid,lesson);}
 String corporate(JdbcTemplate j,TrailTokenService tokens,String email,String role){long uid=j.queryForObject("INSERT INTO company_users(email,password_hash,full_name,email_verified,account_status) VALUES (?,'synthetic','Recruiter test',TRUE,'ACTIVE') RETURNING id",Long.class,email);long company=j.queryForObject("INSERT INTO companies(owner_user_id,legal_name,trade_name,cnpj,phone,industry,address,city,state,verification_status) VALUES (?,'Synthetic','Synthetic company',?,'000','Test','Test','Test','SP','APPROVED') RETURNING id",Long.class,uid,email.startsWith("recruiter")?"11222333000181":email.startsWith("wrong")?"11444777000161":"04252011000110");j.update("INSERT INTO company_members(company_id,user_id,role) VALUES (?,?,?)",company,uid,role);return tokens.issue(EMPRESAS,email,uid,0);}
 HttpResponse<String> send(String method,String path,Object body,String token)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json");if(token!=null)b.header("Authorization","Bearer "+token);return client.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 JsonNode ok(String method,String path,Object body,String token)throws Exception{var r=send(method,path,body,token);assertTrue(r.statusCode()>=200&&r.statusCode()<300,method+" "+path+" => "+r.statusCode()+" "+r.body());return r.body().isBlank()?json.nullNode():json.readTree(r.body());}
